// Clipper2D library is assumed to be available for polygon clipping operations
using namespace Clipper2D;

std::vector<PolygonWithHoles2d> result;
Clipper<IntPoint> clipper;

// Convert input polygons to Clipper format
std::vector<Path> paths1, paths2;
for (const auto& poly : P1.polygons) {
    Path path;
    for (const auto& point : poly) {
        path << IntPoint(point.x, point.y);
    }
    paths1.push_back(path);
}

for (const auto& poly : P2.polygons) {
    Path path;
    for (const auto& point : poly) {
        path << IntPoint(point.x, point.y);
    }
    paths2.push_back(path);
}

// Set up clipping
clipper.AddPaths(paths1, ptSubject, true);
clipper.AddPaths(paths2, ptClip, true);

// Execute intersection
PolyTree polyTree;
clipper.Execute(ctIntersection, polyTree, pftNonZero, pftNonZero);

// Convert result back to PolygonWithHoles2d format
for (const auto& node : polyTree) {
    PolygonWithHoles2d outputPolygon;
    for (const auto& poly : node.Contour) {
        Polygon2d polygon;
        for (const auto& point : poly) {
            polygon.emplace_back(static_cast<double>(point.X) / CLIPPER_SCALE,
                                 static_cast<double>(point.Y) / CLIPPER_SCALE);
        }
        outputPolygon.polygons.push_back(polygon);
    }
    for (const auto& hole : node.Holes) {
        Polygon2d polygon;
        for (const auto& point : hole) {
            polygon.emplace_back(static_cast<double>(point.X) / CLIPPER_SCALE,
                                 static_cast<double>(point.Y) / CLIPPER_SCALE);
        }
        outputPolygon.holes.push_back(polygon);
    }
    result.push_back(outputPolygon);
}

// Handle case where no intersection exists
if (result.empty()) {
    return result;
}

// END_CODE

